sinprog={"2015698","2022660","1000048-B","1000049-B","1000050-B","2023926","2024731","1000051-B","2021185"}
raw={}
for l in open('prereq_raw.jsonl'):
  c,t=json.loads(l); raw[c]=t
def parse(t):
  out=[]
  if t=="NONE": return out
  for blk in re.split(r'(?=Condición \d+)',t):
    m=re.match(r'Condición (\d+)Tipo (\w)¿Todas\? \[(\w)\]Número asignaturas \[(\d*)\]\n',blk)
    if not m: continue
    for ln in blk[m.end():].strip().split('\n'):
      mm=re.match(r'(\d{7}(?:-B)?)(.*)',ln)
      if mm: out.append({"codigo":mm[1],"nombre":mm[2].strip(),"tipo":m[2],"condicion":int(m[1]),"todas":m[3]=="S","correquisito":m[2]=="E"})
  return out
data=[]
for c,n,cr,tp in rows:
  data.append({"codigo":c,"nombre":n,"creditos":cr,"tipologia":tp,"agrupacion":None,"prerrequisitos":parse(raw[c]) if c in raw else None,"semestre":None,"sin_programar_2026_2":c in sinprog})
json.dump(data,open('plan2545.json','w'),ensure_ascii=False,indent=1)
from collections import defaultdict
s=defaultdict(lambda:[0,0])
for d in data: s[d["tipologia"]][0]+=1; s[d["tipologia"]][1]+=d["creditos"]
for k,v in s.items(): print(k,v)
